		'enhancements.canvas_headings': __( 'Shows a small badge with the level (h1 to h6) on every heading in the canvas. A level that jumps ahead, or a second h1, shows a red badge ending in !. Only you see it, it never reaches the page, and it does not block clicking.', 'tokenforge' ),
		'enhancements.canvas_focus': __( 'Numbers every link, button and field in the order the Tab key visits them, so a jumbled order is easy to spot. Only you see it, it never reaches the page, and it does not block clicking.', 'tokenforge' ),
		'enhancements.css_group_top': __( 'Moves the CSS group to the top of the Style tab.', 'tokenforge' ),
		'enhancements.bigger_code_editor': __( 'Makes the CSS code editor taller.', 'tokenforge' ),
		'enhancements.css_autocomplete': __( 'Suggests TokenForge variables and classes while you type in the CSS editor.', 'tokenforge' ),
		'enhancements.ctx_vars_menu': __( 'Right-click a builder input to insert a TokenForge variable (Shift + right-click opens the browser menu).', 'tokenforge' ),
		'enhancements.ctx_class_menu': __( 'Right-click the class field to add or remove TokenForge classes.', 'tokenforge' ),
		'enhancements.original_template_classes': __( 'Remote templates keep their own classes instead of reusing a local class that happens to have the same id.', 'tokenforge' ),
		'enhancements.template_gallery': __( 'A tidier remote-template gallery with full thumbnails.', 'tokenforge' ),

		// ---- Settings ----
		'settings.sync_bricks_vars': __( 'Copies every token into the builder’s global variables, so they appear in its variable picker.', 'tokenforge' ),
		'settings.vars_trans': __( 'Sends the transparent steps of every colour (primary-trans-10 … 90, white-trans-50 …) to the builder\x27s variable list. About 400 variables.', 'tokenforge' ),
		'settings.vars_channels': __( 'Sends the parts colours are built from (primary-hex, primary-rgb, primary-h, primary-s …) to the builder\x27s variable list. You rarely pick these by hand. About 400 variables.', 'tokenforge' ),
		'settings.vars_alt': __( 'Sends the dark mode value of every colour (primary-alt …) to the builder\x27s variable list. The normal colours already switch in dark mode.', 'tokenforge' ),
		'settings.vars_parts': __( 'Sends the variables of buttons, cards, blockquotes and the shop (btn-padding-block, card-radius, woo-badge-color …) to the builder\x27s variable list. Change these in their own sections.', 'tokenforge' ),
		'settings.sync_bricks_colors': __( 'Fills a colour palette in the builder: every colour family as a main colour with its hover colour, and its light, dark and transparent shades grouped under it; then white, black, the background and text colours and your own colours. Each one is its variable, e.g. var(--primary-light), with the same value TokenForge gives it.', 'tokenforge' ),
		'settings.enqueue_in_builder': __( 'Loads the TokenForge stylesheet in the builder canvas so you see the real design while editing.', 'tokenforge' ),
		'settings.category_name': __( 'Name of the variable category and colour palette TokenForge creates in the builder.', 'tokenforge' ),
		'settings.prune_classes': __( 'Removes TokenForge classes from the builder when you switch their feature off.', 'tokenforge' ),
		'settings.prune_variables': __( 'Removes TokenForge variables and colours from the builder when their token is deleted.', 'tokenforge' ),
		'settings.gutenberg_palette': __( 'Which colours the block editor offers: the theme’s, the theme’s plus TokenForge’s, or only TokenForge’s.', 'tokenforge' ),
		'settings.panel_shortcut': __( 'Keys that open and close the TokenForge window in the builder (also with the canvas focused) and on the front end. Click the field, then press the keys.', 'tokenforge' ),
		'settings.frontend_panel': __( 'Lets administrators open this window on the site\x27s pages too, with the shortcut or the admin bar link. Visitors never see it. For the builder, see Show in builder canvas while editing.', 'tokenforge' ),
		'settings.canvas_panel': __( 'Puts a TokenForge button in the corner of the builder\x27s canvas while you edit. It opens the TokenForge window (the same one as the shortcut) and takes the place of the button in the corner of the builder, which its panels can cover. Only you see it, never visitors.', 'tokenforge' ),
		'settings.bricks_theme_sync': __( 'Keeps one theme style in the builder (for the entire website) in step with TokenForge. Its fonts, sizes, colours, container width and section padding point at TokenForge variables, and a change you make in the theme style comes back into TokenForge. Off: TokenForge leaves theme styles alone.', 'tokenforge' ),
		'settings.ui_theme': __( 'How this dashboard looks. Builder panels uses the same dark colours, corners and titles as the builder, so it feels at home there. Flat is a plain graphite look with square corners and a blue accent. Light uses white panels, dark text and a blue accent.', 'tokenforge' ),

		// ---- Modules (switch a whole section off) ----
		'modules.colors': __( 'Off: TokenForge adds no colour classes, dark mode or colour switcher. Colour variables stay, because other parts use them.', 'tokenforge' ),
		'modules.typography': __( 'Off: no text and heading styles, no text size classes and no self-hosted fonts. The size variables stay.', 'tokenforge' ),
		'modules.spacing': __( 'Off: no automatic gaps and no spacing classes. The space variables stay.', 'tokenforge' ),
		'modules.layout': __( 'Off: no section padding, content width, grid classes, sticky header or smooth scrolling.', 'tokenforge' ),
		'modules.borders': __( 'Off: no radius, border, divider or shadow variables and classes.', 'tokenforge' ),
		'modules.buttons': __( 'Off: no button and link styles, and the builder’s buttons keep their own look.', 'tokenforge' ),
		'modules.cards': __( 'Off: no card styles and no corner ribbons.', 'tokenforge' ),
		'modules.icons': __( 'Off: no icon sizes, styles or icon lists.', 'tokenforge' ),
		'modules.forms': __( 'Off: no form field styles.', 'tokenforge' ),
		'modules.content': __( 'Off: no prose styles, flow spacing, rich text or blockquote styles.', 'tokenforge' ),
		'modules.overlays': __( 'Off: no overlay and surface texture classes.', 'tokenforge' ),
		'modules.effects': __( 'Off: no scroll, visible or hover effects.', 'tokenforge' ),
		'modules.base': __( 'Off: no reset, focus rings or helper classes (screen reader text, object fit and so on).', 'tokenforge' ),
		'modules.recipes': __( 'Off: typing ?name no longer expands recipes in the editors.', 'tokenforge' ),
		'modules.builder': __( 'Off: none of the extra builder tools load (context menu, class tools, grid overlay and the rest).', 'tokenforge' ),
		'modules.woo': __( 'Off: TokenForge adds no WooCommerce styles, and WooCommerce (or your builder) styles the shop on its own.', 'tokenforge' ),

