		'woo.enabled': __( 'Adds the WooCommerce styles while WooCommerce is active.', 'tokenforge' ),
		'woo.remove_css': __( 'Stops WooCommerce from loading its own stylesheets, so only your design shows. Some shop parts (the loading spinner, star icons) then need your own CSS. Some builders already do this.', 'tokenforge' ),
		'woo.buttons': __( 'Shop buttons use TokenForge buttons: the classic a.button, button.button and input.button, the builder’s shop buttons and the block buttons.', 'tokenforge' ),
